<template>
  <div class="pcfg-root">
    <header class="pcfg-hero">
      <div class="pcfg-hero__grid"></div>
      <div class="pcfg-hero__inner">
        <div class="pcfg-hero__eyebrow">
          <span class="pcfg-hero__eyebrow-dot"></span>System Configuration
        </div>
        <div class="pcfg-hero__row">
          <div>
            <h1 class="pcfg-hero__title">Performance Calendar</h1>
            <p class="pcfg-hero__sub">
              Define when each phase of the performance cycle is open. Fiscal
              year context is derived automatically from date placement.
            </p>
          </div>
          <div class="pcfg-hero__actions">
            <button
              v-if="!editing"
              class="pcfg-btn pcfg-btn--outline"
              :disabled="loading"
              @click="startEdit"
            >
              <v-icon size="15" color="rgba(255,255,255,0.8)"
                >mdi-pencil-outline</v-icon
              >Edit Configuration
            </button>
            <template v-else>
              <button class="pcfg-btn pcfg-btn--ghost" @click="cancelEdit">
                <v-icon size="15">mdi-close</v-icon> Cancel
              </button>
              <button
                class="pcfg-btn pcfg-btn--save"
                :disabled="saving || !!validationError"
                @click="save"
              >
                <v-icon size="15" v-if="!saving">mdi-check</v-icon>
                <v-progress-circular
                  v-else
                  size="13"
                  width="2"
                  indeterminate
                  color="white"
                />
                {{ saving ? "Saving…" : "Save Changes" }}
              </button>
            </template>
          </div>
        </div>
      </div>
    </header>

    <div v-if="loading" class="pcfg-loading">
      <v-progress-circular
        indeterminate
        color="#6366f1"
        size="36"
        width="3"
      /><span>Loading…</span>
    </div>
    <v-alert v-if="error" type="error" dense outlined class="mx-4 mt-3">{{
      error
    }}</v-alert>

    <div v-if="!loading" class="pcfg-body">
      <!-- Timeline -->
      <div class="pcfg-timeline-card">
        <div class="pcfg-timeline-card__label">
          <v-icon size="14" color="#a5b4fc">mdi-calendar-month-outline</v-icon>
          Annual Overview — fiscal year April → March
        </div>
        <div class="pcfg-timeline">
          <div class="pcfg-timeline__months">
            <div
              v-for="m in MONTHS"
              :key="m.num"
              class="pcfg-timeline__month"
              :style="{ width: 100 / 12 + '%' }"
            >
              {{ m.short }}
            </div>
          </div>
          <div class="pcfg-timeline__bands">
            <div
              v-for="win in timelineWindows"
              :key="win.key"
              class="pcfg-timeline__band"
              :style="win.bandStyle"
              :title="win.label + ': ' + win.startLabel + ' → ' + win.endLabel"
            >
              <span class="pcfg-timeline__band-label">{{ win.short }}</span>
            </div>
          </div>
          <div class="pcfg-timeline__grid">
            <div
              v-for="m in MONTHS"
              :key="m.num"
              class="pcfg-timeline__gridline"
              :style="{ left: ((m.num - 1) / 12) * 100 + '%' }"
            ></div>
          </div>
        </div>
      </div>

      <v-alert
        v-if="editing && validationError"
        type="error"
        dense
        outlined
        class="pcfg-banner"
      >
        <v-icon small left>mdi-close-circle-outline</v-icon
        >{{ validationError }}
      </v-alert>

      <!-- Window cards -->
      <div class="pcfg-grid">
        <div
          v-for="win in windows"
          :key="win.key"
          class="pcfg-card"
          :class="{ 'pcfg-card--editing': editing }"
          :style="{ '--accent': win.color, '--accent-soft': win.colorSoft }"
        >
          <div class="pcfg-card__accent-bar"></div>

          <div class="pcfg-card__head">
            <div class="pcfg-card__icon-wrap">
              <v-icon size="18" :color="win.color">{{ win.icon }}</v-icon>
            </div>
            <div>
              <div class="pcfg-card__title">{{ win.label }}</div>
              <div class="pcfg-card__desc">{{ win.description }}</div>
            </div>
          </div>

          <!-- Context label — reactive to draft in edit mode -->
          <div
            v-if="editing ? draftContext(win.key) : win.context"
            class="pcfg-card__context-row"
          >
            <span
              class="pcfg-context-pill"
              :class="
                'pcfg-context-pill--' +
                  (editing ? draftContext(win.key) : win.context)
              "
            >
              <v-icon
                size="11"
                :color="
                  contextIconColor(
                    editing ? draftContext(win.key) : win.context,
                  )
                "
                >{{
                  contextIcon(editing ? draftContext(win.key) : win.context)
                }}</v-icon
              >
              {{ contextLabel(editing ? draftContext(win.key) : win.context) }}
            </span>
            <span class="pcfg-context-explain">{{
              contextExplain(
                win.key,
                editing ? draftContext(win.key) : win.context,
              )
            }}</span>
          </div>

          <!-- View mode -->
          <div v-if="!editing" class="pcfg-card__dates">
            <div class="pcfg-date-pill">
              <span class="pcfg-date-pill__lbl">From</span>
              <span class="pcfg-date-pill__val">{{
                mmddToMonthDay(win.startDate)
              }}</span>
            </div>
            <v-icon size="14" color="#a8a29e">mdi-arrow-right</v-icon>
            <div class="pcfg-date-pill">
              <span class="pcfg-date-pill__lbl">To</span>
              <span class="pcfg-date-pill__val">{{
                mmddToMonthDay(win.endDate)
              }}</span>
            </div>
            <div class="pcfg-card__duration">
              {{ durationLabel(win.startDate, win.endDate) }}
            </div>
          </div>

          <!-- Edit mode -->
          <div v-else class="pcfg-card__edit-row">
            <div class="pcfg-field">
              <label class="pcfg-field__label">Start (MM-DD)</label>
              <input
                class="pcfg-field__input"
                :class="{
                  'pcfg-field__input--error':
                    draft[win.key] && !isValidMmDd(draft[win.key].startDate),
                }"
                v-model="draft[win.key].startDate"
                placeholder="MM-DD"
                maxlength="5"
                @input="onDraftChange(win.key)"
              />
              <span class="pcfg-field__hint">{{
                mmddToMonthDay(draft[win.key] && draft[win.key].startDate)
              }}</span>
            </div>
            <v-icon size="16" color="#a8a29e" class="pcfg-arrow-icon"
              >mdi-arrow-right</v-icon
            >
            <div class="pcfg-field">
              <label class="pcfg-field__label">End (MM-DD)</label>
              <input
                class="pcfg-field__input"
                :class="{
                  'pcfg-field__input--error':
                    draft[win.key] && !isValidMmDd(draft[win.key].endDate),
                }"
                v-model="draft[win.key].endDate"
                placeholder="MM-DD"
                maxlength="5"
              />
              <span class="pcfg-field__hint">{{
                mmddToMonthDay(draft[win.key] && draft[win.key].endDate)
              }}</span>
            </div>
          </div>

          <!-- Warning (edit mode) -->
          <div
            v-if="
              editing &&
                draft[win.key] &&
                contextWarning(win.key, draft[win.key].startDate)
            "
            class="pcfg-card__warning"
          >
            <v-icon size="12" color="#d97706">mdi-alert-outline</v-icon>
            {{ contextWarning(win.key, draft[win.key].startDate) }}
          </div>

          <!-- Footer: status + override -->
          <div class="pcfg-card__footer">
            <span
              class="pcfg-status-chip"
              :class="'pcfg-status-chip--' + windowStatus(win)"
            >
              <span class="pcfg-status-chip__dot"></span>
              {{
                {
                  active: "Currently Open",
                  upcoming: "Upcoming",
                  closed: "Closed",
                }[windowStatus(win)]
              }}
            </span>
            <!-- Active override chip -->
            <span v-if="activeOverride(win.key)" class="pcfg-override-chip">
              <v-icon size="10" color="#0891b2">mdi-clock-fast</v-icon>
              Extended until
              {{ formatOverrideEnd(activeOverride(win.key).overrideEnd) }}
            </span>
            <!-- Extend button (action windows only) -->
            <button
              v-if="isActionWindow(win.key) && !editing"
              class="pcfg-extend-btn"
              @click="openOverrideDialog(win)"
            >
              <v-icon size="11">mdi-plus</v-icon>
              {{ activeOverride(win.key) ? "Edit Extension" : "Extend" }}
            </button>
          </div>
        </div>
      </div>
    </div>

    <!-- Override dialog -->
    <v-dialog
      v-model="overrideDialog"
      max-width="460"
      content-class="pcfg-dialog-wrap"
    >
      <div class="pcfg-dialog">
        <div
          class="pcfg-dialog__header"
          :style="{ '--accent': overrideDraft.color }"
        >
          <v-icon size="18" :color="overrideDraft.color">{{
            overrideDraft.icon
          }}</v-icon>
          <div>
            <div class="pcfg-dialog__title">
              Extend Window: {{ overrideDraft.label }}
            </div>
            <div class="pcfg-dialog__sub">
              This does not change the original config dates
            </div>
          </div>
        </div>
        <div class="pcfg-dialog__body">
          <div class="pcfg-field pcfg-field--inline">
            <label class="pcfg-field__label">Fiscal Year</label>
            <select
              class="pcfg-field__input"
              v-model="overrideDraft.fiscalYear"
            >
              <option
                v-for="opt in overrideFYOptions()"
                :key="opt.value"
                :value="opt.value"
              >
                {{ opt.label }}
              </option>
            </select>
            <span class="pcfg-field__hint"
              >Extensions may apply to the window's default fiscal year or the
              one immediately before. Moving forward is not permitted.</span
            >
          </div>
          <div class="pcfg-field pcfg-field--inline">
            <label class="pcfg-field__label">Extended Until</label>
            <input
              class="pcfg-field__input"
              v-model="overrideDraft.overrideEnd"
              type="date"
            />
            <span class="pcfg-field__hint"
              >Full date — window stays open until end of this day</span
            >
          </div>
          <div class="pcfg-field pcfg-field--inline">
            <label class="pcfg-field__label">Reason</label>
            <textarea
              class="pcfg-field__textarea"
              v-model="overrideDraft.reason"
              placeholder="e.g. Extension for staff who missed the original deadline"
              rows="3"
            ></textarea>
          </div>
          <!-- Cancel override -->
          <div
            v-if="activeOverride(overrideDraft.key)"
            class="pcfg-dialog__cancel-row"
          >
            <button
              class="pcfg-dialog__cancel-btn"
              @click="cancelOverride(overrideDraft.key)"
            >
              <v-icon size="12" color="#ef4444">mdi-close-circle</v-icon>
              Remove active extension
            </button>
          </div>
        </div>
        <div class="pcfg-dialog__footer">
          <button
            class="pcfg-btn pcfg-btn--ghost"
            style="color:#57534e; border-color:#e7e5e4;"
            @click="overrideDialog = false"
          >
            Cancel
          </button>
          <button
            class="pcfg-btn pcfg-btn--save"
            :disabled="
              savingOverride ||
                !overrideDraft.overrideEnd ||
                !isValidFY(overrideDraft.fiscalYear)
            "
            @click="saveOverride"
          >
            <v-icon size="14" v-if="!savingOverride">mdi-check</v-icon>
            <v-progress-circular
              v-else
              size="12"
              width="2"
              indeterminate
              color="white"
            />
            {{ savingOverride ? "Saving…" : "Save Extension" }}
          </button>
        </div>
      </div>
    </v-dialog>

    <v-snackbar
      v-model="snackbar"
      :color="snackbarColor"
      top
      right
      timeout="3500"
    >
      <v-icon small left>{{
        snackbarColor === "success" ? "mdi-check-circle" : "mdi-alert-circle"
      }}</v-icon>
      {{ snackbarMessage }}
    </v-snackbar>
  </div>
</template>

<script>
import generalMixin from "../../mixins/general";

const WINDOW_META = {
  "semester-1": {
    label: "Semester 1",
    description: "First half of the performance year",
    icon: "mdi-numeric-1-circle-outline",
    color: "#6366f1",
    colorSoft: "#ede9fe",
    short: "S1",
    action: false,
  },
  "semester-2": {
    label: "Semester 2",
    description: "Second half of the performance year",
    icon: "mdi-numeric-2-circle-outline",
    color: "#0891b2",
    colorSoft: "#cffafe",
    short: "S2",
    action: false,
  },
  "goal-settings": {
    label: "Goal Setting",
    description: "Window for staff to define performance objectives",
    icon: "mdi-target",
    color: "#d97706",
    colorSoft: "#fef3c7",
    short: "GS",
    action: true,
  },
  "mid-year-review": {
    label: "Mid-Year Review",
    description: "Goal adjustments and progress check",
    icon: "mdi-calendar-edit",
    color: "#7c3aed",
    colorSoft: "#f5f3ff",
    short: "MR",
    action: true,
  },
  "year-end-review": {
    label: "Year-End Review",
    description: "Final performance scoring and submission",
    icon: "mdi-calendar-check",
    color: "#059669",
    colorSoft: "#ecfdf5",
    short: "YE",
    action: true,
  },
  appeals: {
    label: "Appeals",
    description: "Staff may appeal review scores",
    icon: "mdi-gavel",
    color: "#dc2626",
    colorSoft: "#fee2e2",
    short: "AP",
    action: true,
  },
  finalization: {
    label: "Finalization",
    description: "Scores updated based on appeal outcomes",
    icon: "mdi-check-all",
    color: "#0f766e",
    colorSoft: "#ccfbf1",
    short: "FN",
    action: true,
  },
};

const MONTHS = [
  { num: 1, short: "Jan", days: 31 },
  { num: 2, short: "Feb", days: 28 },
  { num: 3, short: "Mar", days: 31 },
  { num: 4, short: "Apr", days: 30 },
  { num: 5, short: "May", days: 31 },
  { num: 6, short: "Jun", days: 30 },
  { num: 7, short: "Jul", days: 31 },
  { num: 8, short: "Aug", days: 31 },
  { num: 9, short: "Sep", days: 30 },
  { num: 10, short: "Oct", days: 31 },
  { num: 11, short: "Nov", days: 30 },
  { num: 12, short: "Dec", days: 31 },
];

export default {
  name: "PerformanceConfig",
  mixins: [generalMixin],

  data() {
    return {
      MONTHS,
      loading: true,
      saving: false,
      editing: false,
      error: null,
      snackbar: false,
      snackbarMessage: "",
      snackbarColor: "success",
      rawResource: null,
      windows: [],
      draft: {},
      // Overrides
      currentFinancialYear: "",
      overrideRaw: null,
      overrides: {},
      overrideDialog: false,
      savingOverride: false,
      overrideDraft: {
        key: "",
        label: "",
        icon: "",
        color: "",
        context: "",
        fiscalYear: "",
        overrideEnd: "",
        reason: "",
      },
    };
  },

  computed: {
    timelineWindows() {
      return this.windows
        .filter(
          (w) => this.isValidMmDd(w.startDate) && this.isValidMmDd(w.endDate),
        )
        .map((w, i) => {
          const l = this.mmddToFraction(w.startDate),
            r = this.mmddToFraction(w.endDate);
          const wraps = r < l,
            width = wraps ? 1 - l + r : r - l;
          return {
            ...w,
            bandStyle: {
              left: (l * 100).toFixed(2) + "%",
              width: Math.max(width * 100, 1).toFixed(2) + "%",
              background: w.color,
              top: i * 22 + "px",
              opacity: wraps ? "0.75" : "1",
            },
            startLabel: this.mmddToMonthDay(w.startDate),
            endLabel: this.mmddToMonthDay(w.endDate),
          };
        });
    },
    validationError() {
      for (const key of Object.keys(this.draft)) {
        const d = this.draft[key];
        if (!this.isValidMmDd(d.startDate))
          return `${WINDOW_META[key]?.label}: start date "${d.startDate}" is not valid MM-DD`;
        if (!this.isValidMmDd(d.endDate))
          return `${WINDOW_META[key]?.label}: end date "${d.endDate}" is not valid MM-DD`;
      }
      return null;
    },
  },

  async mounted() {
    const [, fy] = await Promise.all([
      Promise.all([this.loadConfig(), this.loadOverrides()]),
      fetch("/site/leave/getFinancialYear")
        .then((r) => r.json())
        .catch(() => null),
    ]);
    if (fy?.year) this.currentFinancialYear = fy.year;
  },

  methods: {
    // ── Config FHIR ──────────────────────────────────────────────
    async loadConfig() {
      this.loading = true;
      this.error = null;
      try {
        const r = await fetch("/fhir/Parameters/performance-config");
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        this.rawResource = await r.json();
        this.windows = this.parseResource(this.rawResource);
      } catch (e) {
        this.error = `Failed to load configuration: ${e.message}`;
      } finally {
        this.loading = false;
      }
    },
    parseResource(resource) {
      return (resource.parameter || [])
        .map((p) => {
          const meta = WINDOW_META[p.name];
          if (!meta) return null;
          const get = (n) => {
            const x = (p.part || []).find((pt) => pt.name === n);
            return x?.valueString || x?.valueDate || "";
          };
          const startDate = get("start-date");
          // Read the stored fiscal-year-context written by save().
          // Fall back to derivation only for legacy resources that predate this field.
          const storedContext = get("fiscal-year-context");
          const context =
            storedContext || this.deriveFiscalYearContext(p.name, startDate);
          return {
            key: p.name,
            ...meta,
            startDate,
            endDate: get("end-date"),
            context,
          };
        })
        .filter(Boolean);
    },
    async save() {
      if (this.validationError) return;
      this.saving = true;
      try {
        const updated = JSON.parse(JSON.stringify(this.rawResource));
        for (const param of updated.parameter || []) {
          const d = this.draft[param.name];
          if (!d) continue;
          if (!param.part) {
            param.part = [];
          }
          for (const part of param.part) {
            if (part.name === "start-date") {
              delete part.valueDate;
              part.valueString = d.startDate;
            }
            if (part.name === "end-date") {
              delete part.valueDate;
              part.valueString = d.endDate;
            }
          }
          // Write the derived fiscal-year-context so all other components can read it
          // directly without needing any derivation logic of their own.
          const derivedContext = this.deriveFiscalYearContext(
            param.name,
            d.startDate,
          );
          if (derivedContext) {
            const ctxPart = (param.part || []).find(
              (p) => p.name === "fiscal-year-context",
            );
            if (ctxPart) {
              ctxPart.valueString = derivedContext;
            } else {
              param.part.push({
                name: "fiscal-year-context",
                valueString: derivedContext,
              });
            }
          }
        }
        const r = await fetch("/fhir/Parameters/performance-config", {
          method: "PUT",
          headers: { "Content-Type": "application/fhir+json" },
          body: JSON.stringify(updated),
        });
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        this.rawResource = await r.json();
        this.windows = this.parseResource(this.rawResource);
        this.editing = false;
        this.showSnackbar("Configuration saved", "success");
      } catch (e) {
        this.showSnackbar(`Save failed: ${e.message}`, "error");
      } finally {
        this.saving = false;
      }
    },
    startEdit() {
      this.draft = {};
      for (const w of this.windows)
        this.$set(this.draft, w.key, {
          startDate: w.startDate,
          endDate: w.endDate,
        });
      this.editing = true;
    },
    cancelEdit() {
      this.editing = false;
      this.draft = {};
    },
    // Force Vue 2 reactivity on nested draft change so context label re-derives instantly
    onDraftChange(key) {
      this.$set(this.draft, key, { ...this.draft[key] });
    },

    // ── Override FHIR ────────────────────────────────────────────
    async loadOverrides() {
      try {
        const r = await fetch("/fhir/Parameters/performance-override-config");
        if (r.status === 404) {
          this.overrideRaw = null;
          this.overrides = {};
          return;
        }
        if (!r.ok) return;
        this.overrideRaw = await r.json();
        this.parseOverrides(this.overrideRaw);
      } catch (_) {
        this.overrides = {};
      }
    },
    parseOverrides(resource) {
      this.overrides = {};
      for (const p of resource.parameter || []) {
        const get = (n) => {
          const x = (p.part || []).find((pt) => pt.name === n);
          return x?.valueString || "";
        };
        this.overrides[p.name] = {
          fiscalYear: get("fiscal-year"),
          overrideEnd: get("override-end"),
          reason: get("reason"),
          status: get("status"),
        };
      }
    },
    activeOverride(key) {
      const ov = this.overrides[key];
      if (!ov || ov.status !== "active") return null;
      if (ov.overrideEnd && new Date(ov.overrideEnd) < new Date()) return null; // expired
      return ov;
    },
    openOverrideDialog(win) {
      const existing = this.overrides[win.key] || {};
      const context =
        win.context || this.deriveFiscalYearContext(win.key, win.startDate);
      const defaultFY = this.fyForContext(context) || this.currentFinancialYear;
      const allowed = [defaultFY, this.shiftFY(defaultFY, -1)];
      const fiscalYear = allowed.includes(existing.fiscalYear)
        ? existing.fiscalYear
        : defaultFY;
      this.overrideDraft = {
        key: win.key,
        label: win.label,
        icon: win.icon,
        color: win.color,
        context,
        fiscalYear,
        overrideEnd: existing.overrideEnd || "",
        reason: existing.reason || "",
      };
      this.overrideDialog = true;
    },
    overrideFYOptions() {
      const ctx = this.overrideDraft.context;
      const defaultFY = this.fyForContext(ctx) || this.currentFinancialYear;
      if (!defaultFY) return [];
      const prior = this.shiftFY(defaultFY, -1);
      return [
        { value: defaultFY, label: `${defaultFY} — default for this window` },
        { value: prior, label: `${prior} — one year prior` },
      ];
    },
    isValidFY(fy) {
      return typeof fy === "string" && /^\d{4}\/\d{4}$/.test(fy);
    },
    async saveOverride() {
      this.savingOverride = true;
      try {
        // Build/update the override resource
        let resource = this.overrideRaw
          ? JSON.parse(JSON.stringify(this.overrideRaw))
          : {
              resourceType: "Parameters",
              id: "performance-override-config",
              meta: {
                profile: [
                  "http://ihris.org/fhir/StructureDefinition/ihris-parameters-remote-config",
                ],
              },
              parameter: [],
            };

        // Ensure parameter array exists
        if (!resource.parameter) {
          resource.parameter = [];
        }

        const idx = resource.parameter.findIndex(
          (p) => p.name === this.overrideDraft.key,
        );

        const parts = [
          { name: "fiscal-year", valueString: this.overrideDraft.fiscalYear },
          { name: "override-end", valueString: this.overrideDraft.overrideEnd },
          { name: "reason", valueString: this.overrideDraft.reason },
          { name: "status", valueString: "active" },
        ];

        if (idx >= 0) {
          // Ensure part array exists on existing parameter
          if (!resource.parameter[idx].part) {
            resource.parameter[idx].part = [];
          }
          resource.parameter[idx].part = parts;
        } else {
          resource.parameter.push({
            name: this.overrideDraft.key,
            part: parts,
          });
        }

        const method = this.overrideRaw ? "PUT" : "POST";
        const url = this.overrideRaw
          ? "/fhir/Parameters/performance-override-config"
          : "/fhir/Parameters";

        const r = await fetch(url, {
          method,
          headers: { "Content-Type": "application/fhir+json" },
          body: JSON.stringify(resource),
        });

        if (!r.ok) throw new Error(`HTTP ${r.status}`);

        this.overrideRaw = await r.json();
        this.parseOverrides(this.overrideRaw);
        this.overrideDialog = false;
        this.showSnackbar("Extension saved", "success");
      } catch (e) {
        this.showSnackbar(`Failed: ${e.message}`, "error");
      } finally {
        this.savingOverride = false;
      }
    },
    async cancelOverride(key) {
      if (!this.overrideRaw) return;

      const resource = JSON.parse(JSON.stringify(this.overrideRaw));

      // Ensure parameter array exists
      if (!resource.parameter) {
        resource.parameter = [];
      }

      const p = resource.parameter.find((x) => x.name === key);
      if (p) {
        // Ensure part array exists
        if (!p.part) {
          p.part = [];
        }
        const s = p.part.find((x) => x.name === "status");
        if (s) {
          s.valueString = "cancelled";
        } else {
          p.part.push({ name: "status", valueString: "cancelled" });
        }
      }

      try {
        const r = await fetch("/fhir/Parameters/performance-override-config", {
          method: "PUT",
          headers: { "Content-Type": "application/fhir+json" },
          body: JSON.stringify(resource),
        });
        if (!r.ok) throw new Error();
        this.overrideRaw = await r.json();
        this.parseOverrides(this.overrideRaw);
        this.overrideDialog = false;
        this.showSnackbar("Extension removed", "success");
      } catch (_) {
        this.showSnackbar("Failed to remove extension", "error");
      }
    },
    formatOverrideEnd(dateStr) {
      if (!dateStr) return "—";
      const d = new Date(dateStr);
      return d.toLocaleDateString("en-GB", {
        day: "numeric",
        month: "short",
        year: "numeric",
      });
    },
    // Advance or retreat a YYYY/YYYY fiscal year string by delta years
    shiftFY(fy, delta) {
      if (!fy || !fy.includes("/")) return fy;
      const [s, e] = fy.split("/").map(Number);
      return `${s + delta}/${e + delta}`;
    },
    isActionWindow(key) {
      return WINDOW_META[key]?.action === true;
    },

    // ── Fiscal year context derivation ───────────────────────────
    deriveFiscalYearContext(key, startDate) {
      if (key === "semester-1" || key === "semester-2") return null;
      if (!this.isValidMmDd(startDate)) return null;
      if (key === "mid-year-review") return "current";
      const inS1 = this.inSemester1(startDate);
      if (key === "goal-settings") return inS1 ? "current" : "next";
      // year-end-review, appeals, finalization all use same rule
      return inS1 ? "previous" : "current";
    },
    draftContext(key) {
      const d = this.draft[key];
      return d && this.isValidMmDd(d.startDate)
        ? this.deriveFiscalYearContext(key, d.startDate)
        : null;
    },
    contextWarning(key, startDate) {
      if (!this.isValidMmDd(startDate)) return null;
      const m = this.mmMonth(startDate);
      if (key === "goal-settings" && this.inSemester1(startDate) && m >= 7)
        return "Goal setting opens late in Semester 1 (July+). Staff may have insufficient time to complete their goals.";
      if (
        (key === "year-end-review" ||
          key === "appeals" ||
          key === "finalization") &&
        this.inSemester2(startDate) &&
        m >= 10 &&
        m <= 11
      )
        return "This window opens early in Semester 2 (Oct–Nov). The performance year has not yet completed.";
      return null;
    },
    contextLabel(c) {
      const base = {
        next: "Next Year",
        current: "Current Year",
        previous: "Previous Year",
      }[c];
      if (!base) return "";
      const fy = this.fyForContext(c);
      return fy ? `${base} (${fy})` : base;
    },
    fyForContext(c) {
      const fy = this.currentFinancialYear;
      if (!fy) return "";
      if (c === "next") return this.shiftFY(fy, 1);
      if (c === "previous") return this.shiftFY(fy, -1);
      if (c === "current") return fy;
      return "";
    },
    contextIcon(c) {
      return (
        {
          next: "mdi-arrow-right-circle",
          current: "mdi-circle-slice-8",
          previous: "mdi-arrow-left-circle",
        }[c] || ""
      );
    },
    contextIconColor(c) {
      return (
        { next: "#0891b2", current: "#059669", previous: "#7c3aed" }[c] ||
        "#a8a29e"
      );
    },
    contextExplain(key, c) {
      return (
        {
          "goal-settings::next":
            "Goals created here apply to the year beginning next April",
          "goal-settings::current":
            "Goals created here apply to the year currently in progress",
          "mid-year-review::current":
            "Reviews the performance plan for the current fiscal year",
          "year-end-review::previous":
            "Closes and scores the year that ended last March",
          "year-end-review::current":
            "Closes and scores the year ending this coming March",
          "appeals::previous":
            "Appeals relate to scores from the year that ended last March",
          "appeals::current":
            "Appeals relate to scores from the year ending this coming March",
          "finalization::previous":
            "Finalizes scores after appeals for last year",
          "finalization::current":
            "Finalizes scores after appeals for the current year",
        }[`${key}::${c}`] || ""
      );
    },

    // ── Date helpers ─────────────────────────────────────────────
    mmMonth(mmdd) {
      return this.isValidMmDd(mmdd) ? parseInt(mmdd.split("-")[0]) : null;
    },
    inSemester1(mmdd) {
      const m = this.mmMonth(mmdd);
      return m !== null && m >= 4 && m <= 9;
    },
    inSemester2(mmdd) {
      const m = this.mmMonth(mmdd);
      return m !== null && (m >= 10 || m <= 3);
    },
    isValidMmDd(val) {
      if (!val || typeof val !== "string" || !/^\d{2}-\d{2}$/.test(val))
        return false;
      const [mm, dd] = val.split("-").map(Number);
      return mm >= 1 && mm <= 12 && dd >= 1 && dd <= 31;
    },
    mmddToMonthDay(val) {
      if (!this.isValidMmDd(val)) return "—";
      const [mm, dd] = val.split("-").map(Number);
      return `${MONTHS[mm - 1].short} ${dd}`;
    },
    mmddToFraction(val) {
      if (!this.isValidMmDd(val)) return 0;
      const [mm, dd] = val.split("-").map(Number);
      return (
        (MONTHS.slice(0, mm - 1).reduce((s, m) => s + m.days, 0) + dd - 1) / 365
      );
    },
    durationLabel(s, e) {
      if (!this.isValidMmDd(s) || !this.isValidMmDd(e)) return "";
      let sf = this.mmddToFraction(s),
        ef = this.mmddToFraction(e);
      if (ef < sf) ef += 1;
      const days = Math.round((ef - sf) * 365);
      return days >= 28 ? `~${Math.round(days / 30.4)} months` : `${days} days`;
    },
    windowStatus(win) {
      const now = new Date();
      const today = this.mmddToFraction(
        String(now.getMonth() + 1).padStart(2, "0") +
          "-" +
          String(now.getDate()).padStart(2, "0"),
      );
      const s = this.mmddToFraction(win.startDate),
        e = this.mmddToFraction(win.endDate);
      const wraps = e < s,
        active = wraps ? today >= s || today <= e : today >= s && today <= e;
      if (active) return "active";
      return (!wraps && today < s) || (wraps && today > e && today < s)
        ? "upcoming"
        : "closed";
    },
    showSnackbar(msg, color) {
      this.snackbarMessage = msg;
      this.snackbarColor = color;
      this.snackbar = true;
    },
  },
};
